// Parse Record v12
// KEY FIXES:
//   1. Zip: use LAST 5-digit number (zip at end, street number at start)
//   2. City loop: only skip 2-letter state codes. NOT full state names.
//      So 'New York, New York, United States' then city='New York' ✓
//      And 'Garden Grove, California' then city='Garden Grove' ✓
//   3. City embedded in street token (for example '7 South Orchard Road Aurora')

const STATES = {
  AL:'Alabama',AK:'Alaska',AZ:'Arizona',AR:'Arkansas',CA:'California',CO:'Colorado',
  CT:'Connecticut',DE:'Delaware',FL:'Florida',GA:'Georgia',HI:'Hawaii',ID:'Idaho',
  IL:'Illinois',IN:'Indiana',IA:'Iowa',KS:'Kansas',KY:'Kentucky',LA:'Louisiana',
  ME:'Maine',MD:'Maryland',MA:'Massachusetts',MI:'Michigan',MN:'Minnesota',
  MS:'Mississippi',MO:'Missouri',MT:'Montana',NE:'Nebraska',NV:'Nevada',
  NH:'New Hampshire',NJ:'New Jersey',NM:'New Mexico',NY:'New York',
  NC:'North Carolina',ND:'North Dakota',OH:'Ohio',OK:'Oklahoma',OR:'Oregon',
  PA:'Pennsylvania',RI:'Rhode Island',SC:'South Carolina',SD:'South Dakota',
  TN:'Tennessee',TX:'Texas',UT:'Utah',VT:'Vermont',VA:'Virginia',
  WA:'Washington',WV:'West Virginia',WI:'Wisconsin',WY:'Wyoming',DC:'District of Columbia'
};
const STATES_REV = Object.fromEntries(Object.entries(STATES).map(([abbr, name]) => [name.toLowerCase(), abbr]));

const STREET_HINT = /^(?:\d+|US-|NJ-|NY-|CA-|TX-|I-\d|Route\b)|\b(?:Street|St|Avenue|Ave|Road|Rd|Boulevard|Blvd|Highway|Hwy|Drive|Dr|Lane|Ln|Court|Ct|Parkway|Pkwy|Plaza|Way|Circle|Cir|Place|Square|Sq|Suite|Ste|Floor|Fl|Building|Bldg|Turnpike|Tpke|Terrace|Ter|Expressway|Expy|Freeway|Fwy|Trail|Trl|Center|Ctr|Canal|Pike|Loop|Pass|Row|Alley|Point|Pointe|Ridge|Grove|Hill|Junction|Landing|Manor|Meadow|Orchard|Park|Ranch|River|Shore|Spring|Spur|Stream|Summit|Track|Union|View|Village|Vista|Walk)\b/i;
const STREET_SUFFIX_SRC = '\\b(?:Street|St|Avenue|Ave|Road|Rd|Boulevard|Blvd|Highway|Hwy|Drive|Dr|Lane|Ln|Court|Ct|Parkway|Pkwy|Way|Circle|Cir|Place|Square|Sq|Suite|Ste|Turnpike|Tpke|Terrace|Ter|Trail|Trl|Center|Ctr|Canal|Pike|Loop|Row|Point|Pointe|Ridge|Grove|Hill|Manor|Orchard|Park|Ranch|River|Shore|Spring|Spur|Stream|Summit|Track|Union|View|Village|Vista|Walk)\\b';

function clean(v) {
  return String(v ?? '').replace(/[\u2018\u2019]/g,"'").replace(/[\u201C\u201D]/g,'"').replace(/\s+/g,' ').trim();
}

function parseState(text) {
  for (const m of text.matchAll(/\b([A-Z]{2})\b/g)) {
    if (STATES[m[1]]) return m[1];
  }
  const lower = text.toLowerCase();
  for (const [name, abbr] of Object.entries(STATES_REV)) {
    if (lower.includes(name)) return abbr;
  }
  return null;
}

function extractCityFromStreet(streetToken) {
  const re = new RegExp(STREET_SUFFIX_SRC, 'gi');
  let last = null, m;
  while ((m = re.exec(streetToken)) !== null) last = m;
  if (!last) return null;
  const after = streetToken.slice(last.index + last[0].length).trim();
  if (after.length >= 3 && /^[A-Za-z][A-Za-z\s]{1,}$/.test(after) && !STATES[after.toUpperCase()]) return after;
  return null;
}

function isJunkCity(part) {
  if (!part) return true;
  if (/^\d+$/.test(part)) return true;            // pure number
  if (STATES[part.toUpperCase()]) return true;     // 2-letter state code ONLY
  // Do NOT reject full state names here: they can also be city names (New York, California)
  return false;
}

function parseLocation(text) {
  const s = clean(text);
  const out = { street: null, city: null, state: parseState(s), zip: null };
  if (!s) return out;

  const zipMatches = [...s.matchAll(/\b(\d{5})(?:-\d{4})?\b/g)];
  if (zipMatches.length > 0) out.zip = zipMatches[zipMatches.length - 1][1];

  const parts = s.split(',').map(clean).filter(Boolean);
  const si = parts.findIndex(p => STREET_HINT.test(p));

  if (si >= 0) {
    out.street = parts[si];
    let found = false;
    for (let i = si + 1; i < parts.length; i++) {
      const maybeCity = parts[i]
        .replace(/\b\d{5}(?:-\d{4})?\b/g, '')
        .replace(/\bUS(A)?\b/gi, '')
        .replace(/\bUnited States\b/gi, '')
        .trim();
      if (maybeCity && !isJunkCity(maybeCity)) { out.city = maybeCity; found = true; break; }
    }
    if (!found) {
      const emb = extractCityFromStreet(parts[si]);
      if (emb) out.city = emb;
    }
  } else {
    for (const p of parts) {
      const maybeCity = p
        .replace(/\b\d{5}(?:-\d{4})?\b/g, '')
        .replace(/\bUS(A)?\b/gi, '')
        .replace(/\bUnited States\b/gi, '')
        .trim();
      if (maybeCity && !isJunkCity(maybeCity)) { out.city = maybeCity; break; }
    }
  }
  return out;
}

function mergeParsed(a, b) {
  return {
    street: a.street || b.street || null,
    city:   a.city   || b.city   || null,
    state:  a.state  || b.state  || null,
    zip:    a.zip    || b.zip    || null
  };
}

function extractCompanyAndLocation(companyField, addressField) {
  let company = clean(companyField);
  let address = clean(addressField);
  let locationSeed = address;

  const mixed = company.match(/^(.+?),\s*([A-Z]{2})(?:\s+\d{5})?\s+-\s+(.+)$/);
  if (mixed && STATES[mixed[2]]) {
    company = clean(mixed[3]);
    locationSeed = clean([mixed[1], mixed[2], address].filter(Boolean).join(', '));
    return { company, locationSeed };
  }

  for (const src of [company, address]) {
    const di = src.indexOf(' - ');
    if (di > 0) {
      const left = clean(src.slice(0, di));
      if (left && !STREET_HINT.test(left) && !/^.+,\s*[A-Z]{2}/.test(left)) {
        company = left;
        locationSeed = clean(src.slice(di + 3));
        return { company, locationSeed };
      }
    }
  }
  return { company, locationSeed };
}

return $input.all().map(item => {
  const f = item.json.fields || item.json;
  const recordId = item.json.id || f.id;
  const rawCompany = clean(f.Company || f.company || '');
  const rawAddress = clean(f.Address || f.address || '');
  const extracted = extractCompanyAndLocation(rawCompany, rawAddress);
  const p1 = parseLocation(rawAddress);
  const p2 = parseLocation(extracted.locationSeed);
  const p  = mergeParsed(p1, p2);
  return { json: {
    record_id: recordId,
    raw_address: rawAddress,
    p_company: extracted.company,
    p_street:  p.street,
    p_zip:     p.zip,
    p_city:    p.city,
    p_state:   p.state
  }};
});

// Score & Decide v12
// Runs ONCE for all input items (runOnceForAllItems mode).
// Input: 0-N flat candidate rows from Search Supabase
// Also reads Parse Record output to get the parsed address fields.
// Always returns exactly 1 output item: handles 0 candidates gracefully.
//
// Scoring priority (company must match first):
//   1. street + zip  then exact address (street takes priority when available)
//   2. street + city
//   3. zip only      then fallback when no street given or no street match
//   4. state + city
//   5. city only
//
// cityOk uses EXACT match only (no full_text contains) to prevent false positives
// for example city 'Norfolk' must not match a record whose city is 'Suffolk'

function norm(v) {
  return String(v ?? '').replace(/[\u2018\u2019]/g,"'").toLowerCase().replace(/[^a-z0-9]+/g,'');
}
function same(a, b) {
  const na = norm(a), nb = norm(b);
  return Boolean(na && nb && na === nb);
}
function contains(haystack, needle) {
  const nh = norm(haystack), nn = norm(needle);
  return Boolean(nh && nn && nh.includes(nn));
}

function candidateScore(row, p) {
  // Company must match (fuzzy: names can vary slightly)
  const companyOk = same(row.company, p.p_company) || contains(row.full_text, p.p_company);
  if (!companyOk) return null;

  const zipOk    = p.p_zip    && String(row.zip   || '') === String(p.p_zip);
  const stateOk  = p.p_state  && String(row.state || '').toUpperCase() === String(p.p_state || '').toUpperCase();
  // EXACT city match only: prevents for example 'Suffolk' matching when city='Norfolk'
  const cityOk   = p.p_city   && same(row.city, p.p_city);
  // Street: fuzzy via full_text contains (handles embedded city in p_street like '7 South Orchard Road Aurora')
  const streetOk = p.p_street && (same(row.street, p.p_street) || contains(row.full_text, p.p_street));

  if (streetOk && zipOk)  return { priority: 1, reason: 'company_street_zip' };
  if (streetOk && cityOk) return { priority: 2, reason: 'company_street_city' };
  if (zipOk)              return { priority: 3, reason: 'company_zip' };
  if (stateOk && cityOk)  return { priority: 4, reason: 'company_state_city' };
  if (cityOk)             return { priority: 5, reason: 'company_city' };
  return null;
}

// Get parsed record from Parse Record node (1 item always present via SplitInBatches)
const parsed = $('Parse Record').first().json;

// All input items are flat candidate rows from Search Supabase (0 to N)
const candidates = $input.all().map(item => item.json);

let best = null;
for (const row of candidates) {
  const score = candidateScore(row, parsed);
  if (score && (!best || score.priority < best.priority)) {
    best = { ...row, priority: score.priority, reason: score.reason };
  }
}

return [{ json: {
  record_id:       parsed.record_id,
  found_match:     Boolean(best),
  matched_address: best ? best.full_text : null,
  match_status:    'Qualified',
  match_reason:    best ? best.reason : 'no_match',
  candidate_count: candidates.length,
  debug_company:   parsed.p_company,
  debug_zip:       parsed.p_zip,
  debug_city:      parsed.p_city,
  debug_state:     parsed.p_state,
  debug_street:    parsed.p_street
}}];
